<?php
declare(strict_types=1);
namespace app\controller\api;
use app\repository\PlayerControlRepository;use app\service\ApiResponder;use app\service\AuditService;use app\service\CsvExportService;use app\service\CsrfTokenService;use app\service\PlayerControlService;use app\service\TenantContext;use InvalidArgumentException;use RuntimeException;use think\Request;use think\Response;
final class PlayerControl
{
    public function index(Request $request,TenantContext $tenant,PlayerControlRepository $repo,ApiResponder $api):Response{$raw=$request->get('channelId');$channel=$tenant->resolveChannelId($raw===null||$raw===''?null:(int)$raw);return $api->success($repo->paginate($channel,['uid'=>$request->get('uid'),'gameId'=>$request->get('gameId'),'currencyCode'=>$request->get('currencyCode'),'state'=>$request->get('state'),'mode'=>$request->get('mode')],max(1,(int)$request->get('page',1)),min(100,max(1,(int)$request->get('pageSize',20)))));}
    public function detail(int $id,Request $request,TenantContext $tenant,PlayerControlRepository $repo,ApiResponder $api):Response{$raw=$request->get('channelId');$channel=$tenant->resolveChannelId($raw===null||$raw===''?null:(int)$raw);$row=$repo->find($channel,$id);return $row?$api->success($row):$api->error('RESOURCE_NOT_FOUND','调控任务不存在或不可见',404);}
    public function options(Request $request,TenantContext $tenant,PlayerControlRepository $repo,ApiResponder $api):Response{$raw=$request->get('channelId');$channel=$tenant->resolveChannelId($raw===null||$raw===''?null:(int)$raw);return $api->success(['games'=>$repo->games(),'currencies'=>$repo->currencies($channel)]);}
    public function export(Request $request,TenantContext $tenant,PlayerControlRepository $repo,CsvExportService $csv,AuditService $audit,ApiResponder $api):Response{$raw=$request->get('channelId');$channel=$tenant->resolveChannelId($raw===null||$raw===''?null:(int)$raw);$filters=['uid'=>$request->get('uid'),'gameId'=>$request->get('gameId'),'currencyCode'=>$request->get('currencyCode'),'state'=>$request->get('state'),'mode'=>$request->get('mode')];$first=$repo->paginate($channel,$filters,1,100);if((int)$first['total']>10000)return $api->error('EXPORT_LIMIT_EXCEEDED','导出结果超过 10000 条，请缩小筛选范围',422);$items=$first['items'];for($page=2,$pages=(int)ceil((int)$first['total']/100);$page<=$pages;$page++){array_push($items,...$repo->paginate($channel,$filters,$page,100)['items']);}$rows=array_map(static fn(array $x):array=>[$x['control_id'],$x['channel_id'],$x['uid'],$x['playername'],$x['game_id'],$x['title'],$x['currency_code'],$x['control_mode'],$x['target_amount'],$x['target_rtp'],$x['progress']['amount'],$x['progress']['actualRtp'],$x['completed_rounds'],$x['max_rounds'],$x['start_at'],$x['end_at'],$x['state'],$x['load_status'],$x['reason'],$x['operator_name'],$x['create_time']],$items);$actor=$tenant->user();$audit->record('player_control.export','success',(string)$request->ip(),(string)$request->header('user-agent',''),(int)$actor['id'],(int)$actor['channel_id'],(string)$actor['role_code'],'player_control','','',null,null,['targetChannelId'=>$channel,'rowCount'=>count($rows)]);return $csv->download('player-controls-'.date('Ymd-His').'.csv',['任务ID','渠道ID','UID','玩家','游戏ID','游戏','币种','模式','目标金额','目标RTP','实际进度','实际RTP','完成局数','最大局数','开始时间戳','结束时间戳','状态','加载状态','原因','操作人','创建时间'],$rows);}
    public function create(Request $request,TenantContext $tenant,CsrfTokenService $csrf,PlayerControlService $service,ApiResponder $api):Response{if(!$csrf->validate('api',(string)$request->header('x-csrf-token','')))return $api->error('CSRF_INVALID','页面已过期，请刷新后重试',419);$raw=$request->post('channelId');$channel=$tenant->resolveChannelId($raw===null||$raw===''?null:(int)$raw);if($channel===null||$channel<=0)return $api->error('VALIDATION_FAILED','请选择商户',422);try{$data=$service->create($channel,$request->post(),$tenant->user(),(string)$request->ip(),(string)$request->header('user-agent',''));$data['csrfToken']=$csrf->issue('api');return $api->success($data,'玩家调控任务已创建',201);}catch(InvalidArgumentException $e){return $api->error('VALIDATION_FAILED',$e->getMessage(),422);}catch(RuntimeException $e){return $api->error($e->getMessage()==='PLAYER_CONTROL_CONFLICT'?'PLAYER_CONTROL_CONFLICT':'RUNTIME_LOAD_FAILED',$e->getMessage()==='PLAYER_CONTROL_CONFLICT'?'该玩家在相同游戏和币种已有生效任务':$e->getMessage(),$e->getMessage()==='PLAYER_CONTROL_CONFLICT'?409:502);}}
    public function cancel(int $id,Request $request,TenantContext $tenant,CsrfTokenService $csrf,PlayerControlService $service,ApiResponder $api):Response{if(!$csrf->validate('api',(string)$request->header('x-csrf-token','')))return $api->error('CSRF_INVALID','页面已过期，请刷新后重试',419);$raw=$request->post('channelId');$channel=$tenant->resolveChannelId($raw===null||$raw===''?null:(int)$raw);if($channel===null||$channel<=0)return $api->error('VALIDATION_FAILED','请选择商户',422);try{$data=$service->cancel($channel,$id,(string)$request->post('reason',''),$tenant->user(),(string)$request->ip(),(string)$request->header('user-agent',''));$data['csrfToken']=$csrf->issue('api');return $api->success($data,'任务已取消');}catch(InvalidArgumentException $e){return $api->error('VALIDATION_FAILED',$e->getMessage(),422);}catch(RuntimeException $e){return $api->error($e->getMessage()==='RESOURCE_NOT_FOUND'?'RESOURCE_NOT_FOUND':'CONTROL_NOT_ACTIVE',$e->getMessage(),$e->getMessage()==='RESOURCE_NOT_FOUND'?404:409);}}
}
